actions.script:
def _valid = ['kpis','health','lowstock','warehouse','recent','movements','category','pricecov','forecast']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }
ec.user.setPreference('INV_DASH_ORDER', _clean.join(','))
if (context.sizes != null) {
    def _sz = ((context.sizes ?: '').toString().split(',') as List)
            .collect { it.split(':') as List }
            .findAll { it.size()==2 && _valid.contains(it[0]) && it[1] in ['half','third'] }
            .collect { it[0]+':'+it[1] }
    ec.user.setPreference('INV_DASH_SIZE', _sz.join(','))
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

import org.moqui.entity.EntityCondition
def ef = ec.entity

// ----- Catalog counts -----
totalProducts  = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).count()
withPrice      = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).condition("mrpAmount", EntityCondition.GREATER_THAN, 0G).count()
missingPrice   = totalProducts - withPrice
categoriesCount= ef.find("mantle.product.category.ProductCategory").condition("ownerPartyId", orgId).count()
facilitiesCount= ef.find("mantle.facility.Facility").condition("ownerPartyId", orgId).count()
trackedCount   = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).condition("inventoryTracked", "Y").count()

// ZE-SHOP: when a shop is selected globally, scope the STOCK figures (units/value/expiring) to its
// facility (null = All Shops). Product/category counts stay org-wide (products belong to the org).
def _activeShop = null; try { def _sc = ec.service.sync().name("zenith.base.ShopServices.get#ActiveShopScope").call(); _activeShop = _sc?.activeShopId } catch (Exception _e) {}

// Warehouse choices never expand the current organization or global shop scope.
def _fq = ef.find("mantle.facility.Facility").condition("ownerPartyId", orgId).orderBy("facilityName")
if (_activeShop) _fq.condition("facilityId", _activeShop)
warehouseOptions = _fq.list()
dashFacilityId = (dashFacilityId ?: '').toString()
if (dashFacilityId && !warehouseOptions.any { it.facilityId == dashFacilityId }) dashFacilityId = ''
if (dashFacilityId) _activeShop = dashFacilityId
warehouseScopeLabel = _activeShop ? (warehouseOptions.find { it.facilityId == _activeShop }?.facilityName ?: 'Current shop') : 'All Warehouses'
def _scopeQoh = [:]
if (_activeShop) {
    ef.find("mantle.product.asset.Asset").condition("ownerPartyId", orgId).condition("facilityId", _activeShop)
      .condition("assetTypeEnumId", "AstTpInventory").list().each { a ->
        _scopeQoh[a.productId] = (_scopeQoh[a.productId] ?: 0G) + (a.quantityOnHandTotal ?: 0G)
    }
}

// ----- Stock value + units in hand (across ALL of the org's inventory) -----
// ZE-INV-001/IV-001: sum per ASSET (not the by-facility view). Two fixes:
//  (1) the by-facility view INNER-joins Facility, so opening stock that has no facility yet
//      (facilityId null) was dropped -> "0 units in stock" even though the catalog shows it;
//  (2) value now falls back valuationRate -> acquireCost -> product MRP (same as the Expiry
//      dashboard, ZE-INV-002), so MRP-priced stock is no longer valued at ₹0.
// NOTE: no explicit type — a `BigDecimal x = ...` at script top level is a LOCAL var in Groovy
// and never reaches the screen binding, so ${stockValue}/${totalUnits} rendered as 0 no matter
// what this loop computed (the original latent cause of "₹0 / 0 units"). Bare assignment = binding.
stockValue = 0G
totalUnits = 0G
def _mrpCache = [:]
def _facVal = [:]; def _facUnits = [:]   // ZE-INV dashboard: per-facility value/units for Stock-by-Warehouse
def _saq = ef.find("mantle.product.asset.Asset").condition("ownerPartyId", orgId)
                    .condition("assetTypeEnumId", "AstTpInventory")
                    .condition("quantityOnHandTotal", EntityCondition.GREATER_THAN, 0G)
if (_activeShop) _saq.condition("facilityId", _activeShop)   // ZE-SHOP
def stockAssets = _saq.list()
for (a in stockAssets) {
    def qoh = (a.quantityOnHandTotal ?: 0G) as java.math.BigDecimal
    totalUnits += qoh
    def vr = a.valuationRate ? (a.valuationRate as java.math.BigDecimal) : null
    def ac = a.acquireCost ? (a.acquireCost as java.math.BigDecimal) : null
    def rate = (vr != null && vr > 0G) ? vr : ((ac != null && ac > 0G) ? ac : null)
    if (rate == null) {
        def mrp = _mrpCache[a.productId]
        if (mrp == null) {
            def p = ef.find("mantle.product.Product").condition("productId", a.productId).one()
            mrp = (p?.mrpAmount ?: 0G) as java.math.BigDecimal
            _mrpCache[a.productId] = mrp
        }
        rate = mrp
    }
    stockValue += qoh * (rate ?: 0G)
    def _fid = a.facilityId ?: '__none__'
    _facVal[_fid] = ((_facVal[_fid] ?: 0G) as java.math.BigDecimal) + qoh * (rate ?: 0G)
    _facUnits[_fid] = ((_facUnits[_fid] ?: 0G) as java.math.BigDecimal) + qoh
}
// ----- Stock by Warehouse: aggregate the SAME per-asset value/units by facility (real data) -----
def _wh = []
for (def _e : _facVal.entrySet()) {
    def _fid2 = _e.key
    def _nm = '— No store —'
    if (_fid2 != '__none__') { def _f = ef.find("mantle.facility.Facility").condition("facilityId", _fid2).useCache(true).one(); _nm = _f?.facilityName ?: _fid2 }
    _wh.add([name: _nm, value: (_e.value ?: 0G),
             valueDisp: zinr.inr(ec.l10n.format((_e.value ?: 0G), '#,##,##0.00')),
             unitsDisp: ec.l10n.format((_facUnits[_fid2] ?: 0G), '#,##0.##')])
}
_wh.sort { x, y -> (y.value <=> x.value) }
warehouseList = _wh
warehouseTotalDisp = zinr.inr(ec.l10n.format((stockValue ?: 0G), '#,##,##0.00'))

// ----- Recent Transactions: recent adjustments + transfers, newest first (real data) -----
def _recent = []
ef.find("zenith.erp.inventory.StockAdjustment").condition("organizationPartyId", orgId).orderBy("-adjustmentDate").limit(8).list().each {
    _recent.add([ts: (it.adjustmentDate?.time ?: 0L), kind: 'Adjustment',
                 dateDisp: (it.adjustmentDate ? ec.l10n.format(it.adjustmentDate, 'dd MMM yyyy, HH:mm') : '—'),
                 ref: (it.stockAdjustmentId ?: ''), detail: (it.adjustmentType ?: '')])
}
ef.find("zenith.erp.inventory.StockTransfer").condition("organizationPartyId", orgId).orderBy("-transferDate").limit(8).list().each {
    _recent.add([ts: (it.transferDate?.time ?: 0L), kind: 'Transfer',
                 dateDisp: (it.transferDate ? ec.l10n.format(it.transferDate, 'dd MMM yyyy, HH:mm') : '—'),
                 ref: (it.transferNumber ?: it.stockTransferId ?: ''), detail: ''])
}
_recent.sort { x, y -> (y.ts <=> x.ts) }
recentTxns = _recent.size() > 8 ? new ArrayList(_recent.subList(0, 8)) : _recent

// ----- Low stock (only for items that actually track quantity) -----
int lowStockCnt = 0
def _lowAll = []
if (trackedCount > 0) {
    def trackedIds = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).condition("inventoryTracked", "Y").list()*.productId
    def psv = ef.find("zenith.erp.inventory.ProductStockView").condition("ownerPartyId", orgId).condition("productId", EntityCondition.IN, trackedIds).list()
    for (r in psv) {
        if (_activeShop && !_scopeQoh.containsKey(r.productId)) continue
        def q = _activeShop ? (_scopeQoh[r.productId] ?: 0G) : (r.totalQoh ?: 0G); def rp = (r.reorderPoint ?: 0G)
        if (rp > 0G && q <= rp) {
            lowStockCnt++
            _lowAll.add([name: (r.productName ?: r.productId), sku: (r.pseudoId ?: ''), q: q,
                         qohDisp: ec.l10n.format(q, '#,##0.##'), rpDisp: ec.l10n.format(rp, '#,##0.##')])
        }
    }
}
lowStockCount = lowStockCnt
_lowAll.sort { x, y -> (x.q <=> y.q) }
lowStockList = _lowAll.size() > 8 ? new ArrayList(_lowAll.subList(0, 8)) : _lowAll

// ----- Expiring within 90 days -----
def cal = java.util.Calendar.getInstance(); cal.add(java.util.Calendar.DAY_OF_YEAR, 90)
def threshold = new java.sql.Timestamp(cal.getTimeInMillis())
def _esq = ef.find("mantle.product.asset.Asset").condition("ownerPartyId", orgId)
                 .condition("expiryDate", EntityCondition.LESS_THAN_EQUAL_TO, threshold)
                 .condition("quantityOnHandTotal", EntityCondition.GREATER_THAN, 0G)
if (_activeShop) _esq.condition("facilityId", _activeShop)   // ZE-SHOP
expiringSoon = _esq.count()

// ----- Activity counts -----
adjCount      = ef.find("zenith.erp.inventory.StockAdjustment").condition("organizationPartyId", orgId).count()
transferCount = ef.find("zenith.erp.inventory.StockTransfer").condition("organizationPartyId", orgId).count()

// ----- Products by category (top 8) -----
def cats = ef.find("mantle.product.category.ProductCategory").condition("ownerPartyId", orgId).list()
def pairs = []
for (c in cats) {
    def n = ef.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", c.productCategoryId).count()
    if (n > 0) pairs.add([name: (c.categoryName ?: c.productCategoryId), n: n])
}
pairs.sort { a, b -> (b.n <=> a.n) }
if (pairs.size() > 8) pairs = pairs.subList(0, 8)
def lbls = []; def vals = []
for (p in pairs) {
    def nm = p.name.toString().replace("'", " ").replace("\"", " ")
    lbls.add("'" + nm + "'"); vals.add(p.n.toString())
}
catLabelsJson = "[" + lbls.join(",") + "]"
catValsJson   = "[" + vals.join(",") + "]"
catHasData    = (vals.size() > 0)

// ----- Price coverage donut -----
priceCoverageJson = "[" + withPrice + "," + missingPrice + "]"

// ----- Sample of products missing a price (actionable): mrpAmount is null OR <= 0 -----
def cf = ef.conditionFactory
def noPriceCond = cf.makeCondition([
    cf.makeCondition("mrpAmount", EntityCondition.EQUALS, null),
    cf.makeCondition("mrpAmount", EntityCondition.LESS_THAN_EQUAL_TO, 0G)
], EntityCondition.OR)
missingPriceList = ef.find("mantle.product.Product").condition("ownerPartyId", orgId)
                     .condition(noPriceCond).orderBy("productName").limit(10).list()

// ===== Demand Forecast infographic (what you'll likely sell next) =====
def today = new java.sql.Date(System.currentTimeMillis())
def myPids = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).selectField("productId").list()*.productId
if (!myPids) myPids = ['__none__']
def dfRows = ef.find("zenith.erp.inventory.DemandForecast")
               .condition("productId", EntityCondition.IN, myPids)
               .condition("periodEnd", EntityCondition.GREATER_THAN_EQUAL_TO, today).list()
// keep the freshest prediction per product
def byProd = [:]
for (r in dfRows) {
    def ex = byProd[r.productId]
    if (ex == null || (r.periodStart != null && (ex.periodStart == null || r.periodStart > ex.periodStart))) byProd[r.productId] = r
}
dfProductCount = byProd.size()
def dlist = new ArrayList(byProd.values())
dlist.sort { a, b -> ((b.forecastQuantity ?: 0G) <=> (a.forecastQuantity ?: 0G)) }
def topN = dlist.size() > 8 ? dlist.subList(0, 8) : dlist
def dfLbls = []; def dfVals = []
dfTopName = "—"; dfTopQty = 0
for (int i = 0; i < topN.size(); i++) {
    def r = topN[i]
    def prod = ef.find("mantle.product.Product").condition("productId", r.productId).one()
    def nm = (prod?.productName ?: r.productId).toString().replace("'", " ").replace("\"", " ")
    if (nm.length() > 24) nm = nm.substring(0, 24)
    def qv = ((r.forecastQuantity ?: 0G) as java.math.BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP)
    dfLbls.add("'" + nm + "'"); dfVals.add(qv.toPlainString())
    if (i == 0) { dfTopName = nm; dfTopQty = qv }
}
dfLabelsJson = "[" + dfLbls.join(",") + "]"
dfValsJson   = "[" + dfVals.join(",") + "]"
dfHasData    = (dfVals.size() > 0)

dfAlertCount = ef.find("zenith.erp.inventory.DemandAlert").condition("organizationPartyId", orgId).condition("statusId", "AlertNew").count()

def accRows = ef.find("zenith.erp.inventory.DemandForecast").condition("productId", EntityCondition.IN, myPids)
                .condition("accuracyPercent", EntityCondition.IS_NOT_NULL, null).selectField("accuracyPercent").list()
dfHasAcc = (accRows != null && accRows.size() > 0)
if (dfHasAcc) {
    def t = 0.0; for (a in accRows) t += (a.accuracyPercent ?: 0)
    dfAvgAcc = (t / accRows.size()).setScale(0, java.math.RoundingMode.HALF_UP)
} else { dfAvgAcc = null }
dfAccWord = !dfHasAcc ? "Still learning" : (dfAvgAcc >= 75 ? "Strong" : (dfAvgAcc >= 60 ? "Good" : (dfAvgAcc >= 45 ? "Fair" : "Still learning")))

dfPlain = "Based on your recent sales, here's roughly what you'll sell in the week ahead — so you know what to keep stocked. We're predicting " + dfProductCount + " products. " +
    (dfAlertCount > 0 ? (dfAlertCount + (dfAlertCount == 1 ? " item is" : " items are") + " selling unusually right now — worth a look.") : "Nothing is behaving unusually right now.")

// ===== ZE-DASH date-range filter + Stock Movements time series =====
// The range drives ONLY the Stock Movements widget; the snapshot KPIs above stay "current" (MARUTHI-safe).
def _sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def _now = ec.user.nowTimestamp
def _todayStr = _sdf.format(_now)
if (!dashDate) dashDate = ''
if (!dashDateTo) dashDateTo = ''
try {
    if (dashDate) java.time.LocalDate.parse(dashDate)
    if (dashDateTo) java.time.LocalDate.parse(dashDateTo)
    if (!dashDate && dashDateTo) dashDate = dashDateTo
} catch (java.time.format.DateTimeParseException ignored) {
    ec.message.addError('Enter valid dates in YYYY-MM-DD format.')
    dashDate = ''; dashDateTo = ''
}
dayStart = null; dayEndExcl = null
if (dashDate) {
    if (!dashDateTo) dashDateTo = dashDate
    if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
    dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
    dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
}
def _cw = java.util.Calendar.getInstance(); _cw.setTime(_now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def _weekStartStr = _sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(_now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def _monthStartStr = _sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(); _c30.setTime(_now); _c30.add(java.util.Calendar.DAY_OF_MONTH,-29); def _last30Str = _sdf.format(_c30.getTime())
urlAll = "?dateMode=all"; urlToday = "?dashDate="+_todayStr+"&dashDateTo="+_todayStr
urlWeek = "?dashDate="+_weekStartStr+"&dashDateTo="+_todayStr
urlMonth = "?dashDate="+_monthStartStr+"&dashDateTo="+_todayStr
url30 = "?dashDate="+_last30Str+"&dashDateTo="+_todayStr
presetActive = 'all'
if (dashDate) {
    presetActive = 'custom'
    if (dashDateTo == _todayStr) {
        if (dashDate == _todayStr) presetActive='today'
        else if (dashDate == _weekStartStr) presetActive='week'
        else if (dashDate == _monthStartStr) presetActive='month'
        else if (dashDate == _last30Str) presetActive='last30'
    }
}
// ZE-DATEWISE: This Year preset + "Date-wise" custom-range tab (self-contained; var-name-agnostic)
def _dwSdf = new java.text.SimpleDateFormat("yyyy-MM-dd"); def _dwNow = ec.user.nowTimestamp; def _dwToday = _dwSdf.format(_dwNow)
def _dwYc = java.util.Calendar.getInstance(); _dwYc.setTime(_dwNow); _dwYc.set(java.util.Calendar.MONTH,0); _dwYc.set(java.util.Calendar.DAY_OF_MONTH,1); def _dwYearStart = _dwSdf.format(_dwYc.getTime())
urlYear = "?dashDate="+_dwYearStart+"&dashDateTo="+_dwToday
if (dashDate && dashDateTo == _dwToday && dashDate == _dwYearStart) presetActive = 'year'
showCustom = (((dateMode ?: '') == 'custom') || (presetActive == 'custom'))
urlCustom = dashDate ? ("?dateMode=custom&dashDate="+dashDate+"&dashDateTo="+dashDateTo) : "?dateMode=custom"
def _ioAssetQuery = ef.find("mantle.product.asset.Asset").condition("ownerPartyId", orgId)
if (_activeShop) _ioAssetQuery.condition("facilityId", _activeShop)
def _ioAssetIds = _ioAssetQuery.selectField("assetId").list()*.assetId as HashSet
def _allTime = !dayStart && dateMode == 'all'
def _mvStart; def _mvEnd
if (dayStart) { _mvStart = dayStart; _mvEnd = dayEndExcl }
else {
    def _c6 = java.util.Calendar.getInstance(); _c6.setTime(_now); _c6.set(java.util.Calendar.DAY_OF_MONTH,1); _c6.add(java.util.Calendar.MONTH,-5); _mvStart = new java.sql.Timestamp(_c6.getTimeInMillis())
    def _ce2 = java.util.Calendar.getInstance(); _ce2.setTime(_now); _ce2.add(java.util.Calendar.DAY_OF_MONTH,1); _mvEnd = new java.sql.Timestamp(_ce2.getTimeInMillis())
    if (_allTime) {
        def _starts = []
        def _first = ef.find("mantle.product.asset.AssetDetail").condition("assetId", EntityCondition.IN, _ioAssetIds ? (_ioAssetIds as List) : ['__none__']).condition("quantityOnHandDiff", EntityCondition.NOT_EQUAL, 0G).condition("effectiveDate", EntityCondition.LESS_THAN, _mvEnd).orderBy("effectiveDate").limit(1).list()
        if (_first) _starts.add(_first[0].effectiveDate)
        if (!_activeShop) {
            def _firstAdj = ef.find("zenith.erp.inventory.StockAdjustment").condition("organizationPartyId", orgId).condition("adjustmentDate", EntityCondition.LESS_THAN, _mvEnd).orderBy("adjustmentDate").limit(1).list()
            def _firstTrf = ef.find("zenith.erp.inventory.StockTransfer").condition("organizationPartyId", orgId).condition("transferDate", EntityCondition.LESS_THAN, _mvEnd).orderBy("transferDate").limit(1).list()
            if (_firstAdj) _starts.add(_firstAdj[0].adjustmentDate)
            if (_firstTrf) _starts.add(_firstTrf[0].transferDate)
        }
        if (_starts) _mvStart = java.sql.Timestamp.valueOf(_sdf.format(_starts.min()) + ' 00:00:00')
    }
}
def _rangeDays = (_mvEnd.getTime() - _mvStart.getTime()) / (1000L*60*60*24)
def _daily = _rangeDays <= 62
def _yearly = _rangeDays > 365 * 30
def _bfmt = new java.text.SimpleDateFormat(_daily ? "yyyy-MM-dd" : (_yearly ? "yyyy" : "yyyy-MM"))
def _lfmt = new java.text.SimpleDateFormat(_daily ? "dd MMM" : (_yearly ? "yyyy" : "MMM yy"))
def _adjs = ef.find("zenith.erp.inventory.StockAdjustment").condition("organizationPartyId", orgId).condition("adjustmentDate", EntityCondition.GREATER_THAN_EQUAL_TO, _mvStart).condition("adjustmentDate", EntityCondition.LESS_THAN, _mvEnd).selectField("adjustmentDate").list()
def _trfs = ef.find("zenith.erp.inventory.StockTransfer").condition("organizationPartyId", orgId).condition("transferDate", EntityCondition.GREATER_THAN_EQUAL_TO, _mvStart).condition("transferDate", EntityCondition.LESS_THAN, _mvEnd).selectField("transferDate").list()
// ZE-INV §7: Stock In/Out FLOW from the AssetDetail ledger (org-scoped; AssetDetail is small). Positive
// quantityOnHandDiff = stock in, negative = stock out. Real data — no fabrication.
def _ioLedger = ef.find("mantle.product.asset.AssetDetail").condition("effectiveDate", EntityCondition.GREATER_THAN_EQUAL_TO, _mvStart).condition("effectiveDate", EntityCondition.LESS_THAN, _mvEnd).selectField("assetId").selectField("effectiveDate").selectField("quantityOnHandDiff").list().findAll { _ioAssetIds.contains(it.assetId) }
def _keys = []; def _labelByKey = [:]; def _adjBy = [:]; def _trfBy = [:]; def _ioInBy = [:]; def _ioOutBy = [:]
def _bc = java.util.Calendar.getInstance(); _bc.setTime(_mvStart); def _bendMs = _mvEnd.getTime(); int _guard = 0
if (!_daily) _bc.set(java.util.Calendar.DAY_OF_MONTH, 1)
if (_yearly) _bc.set(java.util.Calendar.MONTH, 0)
while (_bc.getTimeInMillis() < _bendMs && _guard < 10000) {
    def _k = _bfmt.format(_bc.getTime())
    if (!_labelByKey.containsKey(_k)) { _keys.add(_k); _labelByKey[_k] = _lfmt.format(_bc.getTime()); _adjBy[_k]=0; _trfBy[_k]=0; _ioInBy[_k]=0G; _ioOutBy[_k]=0G }
    _bc.add(_daily ? java.util.Calendar.DAY_OF_MONTH : (_yearly ? java.util.Calendar.YEAR : java.util.Calendar.MONTH), 1); _guard++
}
_adjs.each { def _k = _bfmt.format(it.adjustmentDate); if (_adjBy.containsKey(_k)) _adjBy[_k] = _adjBy[_k] + 1 }
_trfs.each { def _k = _bfmt.format(it.transferDate); if (_trfBy.containsKey(_k)) _trfBy[_k] = _trfBy[_k] + 1 }
_ioLedger.each { def _k = _bfmt.format(it.effectiveDate); if (_ioInBy.containsKey(_k)) { def _d = (it.quantityOnHandDiff ?: 0G) as BigDecimal; if (_d > 0G) _ioInBy[_k] = ((_ioInBy[_k] ?: 0G) as BigDecimal) + _d else _ioOutBy[_k] = ((_ioOutBy[_k] ?: 0G) as BigDecimal) + _d.abs() } }
def _mlbls=[]; def _madj=[]; def _mtrf=[]; def _mIn=[]; def _mOut=[]
_keys.each { _k -> _mlbls.add("'"+_labelByKey[_k]+"'"); _madj.add(_adjBy[_k]); _mtrf.add(_trfBy[_k]); _mIn.add(_ioInBy[_k]); _mOut.add(_ioOutBy[_k]) }
mvLabelsJson = "["+_mlbls.join(",")+"]"; mvAdjJson = "["+_madj.join(",")+"]"; mvTrfJson = "["+_mtrf.join(",")+"]"
mvInJson = "["+_mIn.join(",")+"]"; mvOutJson = "["+_mOut.join(",")+"]"
def _ioInTot = 0G; def _ioOutTot = 0G; _ioInBy.values().each { _ioInTot += it }; _ioOutBy.values().each { _ioOutTot += it }
mvInTotalDisp = ec.l10n.format(_ioInTot, '#,##0.##'); mvOutTotalDisp = ec.l10n.format(_ioOutTot, '#,##0.##')
mvAdjCount = _adjs.size(); mvTrfCount = _trfs.size(); mvHasData = _activeShop ? !_ioLedger.isEmpty() : ((_adjs.size() + _trfs.size() + _ioLedger.size()) > 0)
mvRangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + " to " + dashDateTo)) : (_allTime ? "All time" : "last 6 months")
// ZE-INV §5: week-over-week units delta = net AssetDetail movement in the last 7 days (org-scoped) — real.
def _ioWc7 = java.util.Calendar.getInstance(); _ioWc7.setTime(_now); _ioWc7.add(java.util.Calendar.DAY_OF_MONTH, -7); def _ioWkAgo = new java.sql.Timestamp(_ioWc7.getTimeInMillis())
def _ioWkNet = 0G
ef.find("mantle.product.asset.AssetDetail").condition("effectiveDate", EntityCondition.GREATER_THAN_EQUAL_TO, _ioWkAgo).selectField("assetId").selectField("quantityOnHandDiff").list().each { if (_ioAssetIds.contains(it.assetId)) _ioWkNet = _ioWkNet + ((it.quantityOnHandDiff ?: 0G) as BigDecimal) }
unitsDeltaZero = (_ioWkNet.signum() == 0)
unitsDeltaUp = (_ioWkNet.signum() > 0)
unitsDeltaDisp = (unitsDeltaUp ? '+' : '') + ec.l10n.format(_ioWkNet, '#,##0.##')

// ZE-DASH layout: switchable widgets (+ cashier role default) + saved drag order
def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'movements,category,pricecov,forecast'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('INV_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showKpis = !_hiddenSet.contains('kpis'); showHealth = !_hiddenSet.contains('health'); showMovements = !_hiddenSet.contains('movements')
showCategory = !_hiddenSet.contains('category'); showPricecov = !_hiddenSet.contains('pricecov'); showForecast = !_hiddenSet.contains('forecast')
w_kpis = showKpis ? 'Y' : ''; w_health = showHealth ? 'Y' : ''; w_movements = showMovements ? 'Y' : ''
w_category = showCategory ? 'Y' : ''; w_pricecov = showPricecov ? 'Y' : ''; w_forecast = showForecast ? 'Y' : ''
showLowstock = !_hiddenSet.contains('lowstock'); showWarehouse = !_hiddenSet.contains('warehouse'); showRecent = !_hiddenSet.contains('recent')
w_lowstock = showLowstock ? 'Y' : ''; w_warehouse = showWarehouse ? 'Y' : ''; w_recent = showRecent ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('INV_DASH_ORDER') ?: '')
// ZE-DASH-ARRANGE: default the two chart widgets to half-width so /apps shows them side-by-side (2-col,
