// ========================================================================================
// inventory-dashboard mockup restructure (real data only — NO fabricated deltas)
// ========================================================================================
// §5 Stock In / Stock Out over the last 7 days + the prior 7 days (for a REAL % delta), from the
// AssetDetail ledger scoped to this org's assets (positive diff = in, negative = out).
def _wc7 = java.util.Calendar.getInstance(); _wc7.setTime(_now); _wc7.add(java.util.Calendar.DAY_OF_MONTH,-7); def _wk7Ts = new java.sql.Timestamp(_wc7.getTimeInMillis())
def _wc14 = java.util.Calendar.getInstance(); _wc14.setTime(_now); _wc14.add(java.util.Calendar.DAY_OF_MONTH,-14); def _wk14Ts = new java.sql.Timestamp(_wc14.getTimeInMillis())
def _wkIn=0G; def _wkOut=0G; def _pwIn=0G; def _pwOut=0G
ef.find("mantle.product.asset.AssetDetail").condition("effectiveDate", EntityCondition.GREATER_THAN_EQUAL_TO, _wk14Ts).selectField("assetId").selectField("effectiveDate").selectField("quantityOnHandDiff").list().each {
    if (!_ioAssetIds.contains(it.assetId)) return
    def _d = (it.quantityOnHandDiff ?: 0G) as BigDecimal
    def _cur = (it.effectiveDate != null && it.effectiveDate.time >= _wk7Ts.time)
    if (_d > 0G) { if (_cur) _wkIn += _d else _pwIn += _d }
    else if (_d < 0G) { if (_cur) _wkOut += _d.abs() else _pwOut += _d.abs() }
}
weekInDisp = ec.l10n.format(_wkIn, '#,##0.##'); weekOutDisp = ec.l10n.format(_wkOut, '#,##0.##')
def _pct = { cur, prev -> (prev == null || prev == 0G) ? null : (((cur - prev) / prev) * 100G).setScale(1, java.math.RoundingMode.HALF_UP) }
def _inDelta = _pct(_wkIn, _pwIn); def _outDelta = _pct(_wkOut, _pwOut)
def _inUp = (_inDelta != null && _inDelta >= 0G); def _outUp = (_outDelta != null && _outDelta >= 0G)
kpiInSub  = (_inDelta  == null) ? 'units received (7d)' : ((_inUp?'▲ ':'▼ ') + (_inDelta>=0G?'+':'') + _inDelta + '% vs last week')
kpiOutSub = (_outDelta == null) ? 'units issued (7d)'   : ((_outUp?'▲ ':'▼ ') + (_outDelta>=0G?'+':'') + _outDelta + '% vs last week')
kpiInColor  = (_inDelta  == null) ? '#9CA3AF' : (_inUp  ? '#059669' : '#DC2626')
kpiOutColor = (_outDelta == null) ? '#9CA3AF' : (_outUp ? '#059669' : '#DC2626')

// §5 preformatted KPI display strings
totalItemsDisp = ec.l10n.format(totalProducts ?: 0, '#,##0')
stockValueDispK = zinr.inr(ec.l10n.format(stockValue ?: 0, '#,##,##0'))
lowStockCountDisp = ec.l10n.format(lowStockCount ?: 0, '#,##0')
def _tuDisp = ec.l10n.format(totalUnits ?: 0, '#,##0')
kpiValSub = unitsDeltaZero ? (_tuDisp + ' units in stock') : (_tuDisp + ' units · ' + unitsDeltaDisp + ' this week')
kpiValColor = unitsDeltaZero ? '#9CA3AF' : (unitsDeltaUp ? '#059669' : '#DC2626')

// §9 Recent Transactions as ITEM-LEVEL movements from the ledger (newest first) — real.
def _rMoves = []; def _pNameCache = [:]
def _rlRows = ef.find("mantle.product.asset.AssetDetail").condition("assetId", EntityCondition.IN, _ioAssetIds ? (_ioAssetIds as List) : ['__none__']).condition("quantityOnHandDiff", EntityCondition.NOT_EQUAL, 0G).orderBy("-effectiveDate,assetDetailId").limit(50).list()
for (r in _rlRows) {
    if (!_ioAssetIds.contains(r.assetId)) continue
    def _d = (r.quantityOnHandDiff ?: 0G) as BigDecimal
    if (_d == 0G) continue
    def _asset = ef.find("mantle.product.asset.Asset").condition("assetId", r.assetId).useCache(true).one()
    def _pid = _asset?.productId
    def _pn = _pNameCache.containsKey(_pid) ? _pNameCache[_pid] : null
    if (_pn == null) { def _p = _pid ? ef.find("mantle.product.Product").condition("productId", _pid).useCache(true).one() : null; _pn = (_p?.productName ?: _pid ?: '—'); _pNameCache[_pid] = _pn }
    def _rate = (_asset?.valuationRate ?: _asset?.acquireCost ?: 0G) as BigDecimal
    def _amt = _d.abs() * (_rate ?: 0G)
    _rMoves.add([name:_pn,
                 dateDisp:(r.effectiveDate ? ec.l10n.format(r.effectiveDate, 'dd MMM yyyy, HH:mm') : '—'),
                 isIn:(_d > 0G),
                 qtyDisp:((_d>0G?'+':'−') + ec.l10n.format(_d.abs(), '#,##0.##')),
                 amtDisp:('₹' + ec.l10n.format(_amt, '#,##,##0.00'))])
    if (_rMoves.size() >= 8) break
}
recentMoves = _rMoves; recentMovesHas = (_rMoves.size() > 0)

// §11 Data-completeness breakdown — REAL fields only (the mockup's "purchase price"/"other" have no
// backing field here, so use the fields that exist: price / tax code / barcode / category / description).
def _allProds = ef.find("mantle.product.Product").condition("ownerPartyId", orgId).selectField("productId").selectField("mrpAmount").selectField("hsnCode").selectField("description").list()
def _noPrice=[] as HashSet; def _noHsn=[] as HashSet; def _noDesc=[] as HashSet
for (p in _allProds) {
    def _mv = p.mrpAmount; if (_mv == null || (_mv as BigDecimal) <= 0G) _noPrice.add(p.productId)
    if (!p.hsnCode) _noHsn.add(p.productId)
    if (!p.description) _noDesc.add(p.productId)
}
def _barPids = ef.find("mantle.product.ProductIdentification").condition("productId", EntityCondition.IN, myPids).selectField("productId").list()*.productId as HashSet
def _catPids = ef.find("mantle.product.category.ProductCategoryMember").condition("productId", EntityCondition.IN, myPids).selectField("productId").list()*.productId as HashSet
def _noBar = new HashSet(myPids); _noBar.removeAll(_barPids); if (_noBar.contains('__none__')) _noBar.remove('__none__')
def _noCat = new HashSet(myPids); _noCat.removeAll(_catPids); if (_noCat.contains('__none__')) _noCat.remove('__none__')
compRows = [ [label:'Selling price not set', n:_noPrice.size()],
             [label:'Tax code (HSN/SAC) not set', n:_noHsn.size()],
             [label:'Barcode not set', n:_noBar.size()],
             [label:'Category not set', n:_noCat.size()],
             [label:'Description not set', n:_noDesc.size()] ]
def _anyMiss = new HashSet(); _anyMiss.addAll(_noPrice); _anyMiss.addAll(_noHsn); _anyMiss.addAll(_noDesc); _anyMiss.addAll(_noBar); _anyMiss.addAll(_noCat)
compTotal = _anyMiss.size(); compTotalDisp = ec.l10n.format(compTotal, '#,##0')
compHas = (compTotal > 0)

